"""The invoice domain: customers, line items and invoices.

Every model is immutable once built, strips its strings and rejects unknown fields.
"""

from datetime import date
from decimal import Decimal
from typing import List, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

CURRENCIES = ("USD", "EUR", "GBP")
NUMBER_PATTERN = r"^INV-\d{4}-\d{4}$"
SKU_PATTERN = r"^[A-Z]{3}-\d{3}$"
EMAIL_PATTERN = r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$"
VAT_PATTERN = r"^[A-Z]{2}[0-9A-Z]{2,12}$"
CENTS = Decimal("0.01")


class Customer(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True, frozen=True, extra="forbid")

    name: str = Field(..., min_length=1, max_length=80)
    email: str = Field(..., pattern=EMAIL_PATTERN)
    vat_id: Optional[str] = Field(None, pattern=VAT_PATTERN)
    country: str = Field("US", min_length=2, max_length=2)

    @field_validator("country")
    @classmethod
    def country_code_is_upper(cls, value: str) -> str:
        return value.upper()

    @field_validator("email")
    @classmethod
    def email_is_lower(cls, value: str) -> str:
        return value.lower()


class LineItem(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True, frozen=True, extra="forbid")

    sku: str = Field(..., pattern=SKU_PATTERN)
    description: str = Field(..., min_length=1, max_length=200)
    quantity: int = Field(..., gt=0, le=10000)
    unit_price: Decimal = Field(..., ge=0, max_digits=10, decimal_places=2)
    discount_pct: Decimal = Field(Decimal("0"), ge=0, le=100)

    @field_validator("sku", mode="before")
    @classmethod
    def sku_is_upper(cls, value):
        if isinstance(value, str):
            return value.strip().upper()
        return value

    @property
    def gross(self) -> Decimal:
        return (self.unit_price * self.quantity).quantize(CENTS)

    @property
    def net(self) -> Decimal:
        kept = (Decimal(100) - self.discount_pct) / Decimal(100)
        return (self.unit_price * self.quantity * kept).quantize(CENTS)


class Invoice(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True, frozen=True, extra="forbid")

    number: str = Field(..., pattern=NUMBER_PATTERN)
    kind: Literal["invoice"] = "invoice"
    customer: Customer
    issued: date
    due: date
    currency: str = Field("USD", min_length=3, max_length=3)
    items: List[LineItem] = Field(..., min_length=1, max_length=50)
    reference: Optional[str] = None
    notes: Optional[str] = Field(None, max_length=500)

    @field_validator("currency")
    @classmethod
    def currency_is_known(cls, value: str) -> str:
        value = value.upper()
        if value not in CURRENCIES:
            raise ValueError(f"unsupported currency {value!r}; use one of {', '.join(CURRENCIES)}")
        return value

    @model_validator(mode="after")
    def due_is_not_before_issued(self) -> "Invoice":
        if self.due < self.issued:
            raise ValueError("due date is before the issue date")
        return self

    @property
    def subtotal(self) -> Decimal:
        return sum((item.net for item in self.items), Decimal("0")).quantize(CENTS)

    @property
    def item_count(self) -> int:
        return sum(item.quantity for item in self.items)

    def with_reference(self, reference: str) -> "Invoice":
        return self.model_copy(update={"reference": reference.strip()})

"""Money: line totals, subtotal, tax, total and discounts. All amounts are Decimals to the cent."""

from decimal import ROUND_HALF_UP, Decimal
from typing import List

from invoicer.errors import InvoiceError
from invoicer.models import CENTS, Invoice
from invoicer.settings import BillingSettings


def _cents(amount: Decimal) -> Decimal:
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


def line_totals(invoice: Invoice) -> List[dict]:
    """Each line as a dict with its gross and net amounts added."""
    rows = []
    for item in invoice.items:
        row = item.model_dump()
        row["gross"] = item.gross
        row["net"] = item.net
        rows.append(row)
    return rows


def subtotal(invoice: Invoice) -> Decimal:
    return invoice.subtotal


def tax(invoice: Invoice, settings: BillingSettings) -> Decimal:
    return _cents(invoice.subtotal * settings.tax_rate)


def total(invoice: Invoice, settings: BillingSettings) -> Decimal:
    return _cents(invoice.subtotal + tax(invoice, settings))


def late_fee(invoice: Invoice, settings: BillingSettings, days_late: int) -> Decimal:
    """A flat percentage of the total once an invoice is late, zero otherwise."""
    if days_late <= 0:
        return Decimal("0.00")
    return _cents(total(invoice, settings) * settings.late_fee_pct / Decimal(100))


def apply_discount(invoice: Invoice, pct: Decimal) -> Invoice:
    """A new invoice with every line discounted by ``pct`` percent; the original is unchanged."""
    pct = Decimal(pct)
    if pct < 0 or pct > 100:
        raise InvoiceError(f"discount must be between 0 and 100 percent, not {pct}")
    items = [item.model_copy(update={"discount_pct": pct}) for item in invoice.items]
    return invoice.model_copy(update={"items": items})


def split_by_sku(invoice: Invoice) -> dict:
    """Net amount per SKU, merging repeated SKUs."""
    totals: dict = {}
    for item in invoice.items:
        totals[item.sku] = _cents(totals.get(item.sku, Decimal("0")) + item.net)
    return totals

"""Reports over invoices: summary lines, per-customer totals, overdue invoices and rows."""

from datetime import date
from decimal import Decimal
from typing import Dict, Iterable, List

from invoicer.models import CENTS, Invoice
from invoicer.pricing import total
from invoicer.settings import BillingSettings


def summary_line(invoice: Invoice, settings: BillingSettings) -> str:
    amount = total(invoice, settings)
    return f"{invoice.number} {invoice.customer.name}: {invoice.item_count} items, {amount} {invoice.currency}, due {invoice.due.isoformat()}"


def customer_totals(invoices: Iterable[Invoice], settings: BillingSettings) -> Dict[str, Decimal]:
    """Total billed per customer name, sorted by name."""
    totals: Dict[str, Decimal] = {}
    for invoice in invoices:
        name = invoice.customer.name
        totals[name] = (totals.get(name, Decimal("0")) + total(invoice, settings)).quantize(CENTS)
    return dict(sorted(totals.items()))


def overdue(invoices: Iterable[Invoice], today: date) -> List[str]:
    """Numbers of the invoices whose due date is before ``today``, oldest first."""
    late = [invoice for invoice in invoices if invoice.due < today]
    late.sort(key=lambda invoice: (invoice.due, invoice.number))
    return [invoice.number for invoice in late]


def as_rows(invoices: Iterable[Invoice], settings: BillingSettings) -> List[dict]:
    """One flat row per invoice: number, dates, currency, item count and total."""
    rows = []
    for invoice in invoices:
        row = invoice.model_dump(include={"number", "issued", "due", "currency"})
        row["items"] = invoice.item_count
        row["total"] = total(invoice, settings)
        rows.append(row)
    return rows


def by_currency(invoices: Iterable[Invoice], settings: BillingSettings) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for invoice in invoices:
        totals[invoice.currency] = (totals.get(invoice.currency, Decimal("0")) + total(invoice, settings)).quantize(CENTS)
    return totals

"""Invoices as JSON and plain dicts, and the JSON schema clients validate against."""

import json

from invoicer.models import Invoice


def invoice_to_json(invoice: Invoice) -> str:
    """Stable JSON: sorted keys, two-space indent, dates as ISO strings, decimals as strings."""
    return json.dumps(invoice.model_dump(mode="json"), indent=2, sort_keys=True)


def invoice_from_json(text: str) -> Invoice:
    return Invoice.model_validate_json(text)


def invoice_from_dict(data: dict) -> Invoice:
    return Invoice.model_validate(data)


def invoice_schema() -> dict:
    """The invoice's JSON schema."""
    return Invoice.model_json_schema()


def to_record(invoice: Invoice) -> dict:
    """The invoice as a flat record for storage: the customer's name only, no notes."""
    data = invoice.model_dump(exclude={"notes", "customer"})
    data["customer_name"] = invoice.customer.name
    data["subtotal"] = invoice.subtotal
    return data


def items_as_dicts(invoice: Invoice) -> list:
    """Each line as plain values (strings for decimals), ready for JSON."""
    return [
        {
            "sku": item.sku,
            "description": item.description,
            "quantity": item.quantity,
            "unit_price": str(item.unit_price),
            "discount_pct": str(item.discount_pct),
        }
        for item in invoice.items
    ]

"""Billing settings, from the environment (prefix ``INVOICER_``) or explicit overrides."""

from decimal import Decimal

from pydantic import Field, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

from invoicer.models import CURRENCIES


class BillingSettings(BaseSettings):
    model_config = SettingsConfigDict(env_prefix="INVOICER_", case_sensitive=False, str_strip_whitespace=True)

    tax_rate: Decimal = Field(Decimal("0.0825"), ge=0, le=1)
    currency: str = "USD"
    payment_days: int = Field(30, ge=1, le=365)
    company_name: str = Field("Acme Billing", min_length=1)
    late_fee_pct: Decimal = Field(Decimal("1.5"), ge=0, le=20)

    @field_validator("currency")
    @classmethod
    def currency_is_known(cls, value: str) -> str:
        value = value.upper()
        if value not in CURRENCIES:
            raise ValueError(f"unsupported currency {value!r}")
        return value


def load_settings(**overrides) -> BillingSettings:
    """Settings from the environment, with explicit keyword overrides winning."""
    return BillingSettings(**overrides)


def settings_summary(settings: BillingSettings) -> dict:
    """The settings as plain values, for logging."""
    return settings.model_dump()

"""Validating raw payloads before they become invoices: every problem as a plain record."""

from dataclasses import dataclass
from typing import Dict, List, Tuple

from pydantic import ValidationError

from invoicer.models import Invoice


@dataclass(frozen=True)
class Problem:
    loc: Tuple
    type: str
    message: str

    @property
    def field(self) -> str:
        return ".".join(str(part) for part in self.loc)


def validate_payload(data: dict) -> List[Problem]:
    """Every validation problem of ``data`` as an invoice, in pydantic's order; [] when it is valid.
    ``type`` is pydantic's own error type code."""
    try:
        Invoice.model_validate(data)
    except ValidationError as error:
        return [Problem(loc=tuple(item["loc"]), type=item["type"], message=item["msg"]) for item in error.errors()]
    return []


def is_valid(data: dict) -> bool:
    return not validate_payload(data)


def problems_by_field(data: dict) -> Dict[str, List[str]]:
    """Problem messages grouped by dotted field name."""
    grouped: Dict[str, List[str]] = {}
    for problem in validate_payload(data):
        grouped.setdefault(problem.field, []).append(problem.message)
    return grouped


def field_names() -> List[str]:
    """The invoice's field names, in declaration order."""
    return list(Invoice.model_fields)


def describe_fields() -> Dict[str, bool]:
    """Each invoice field and whether it is required."""
    return {name: field.is_required() for name, field in Invoice.model_fields.items()}
